"""Format already computed Colab JSON into bounded D1/D2 reports; no score computation."""
import json,pathlib,hashlib,collections
ROOT=pathlib.Path(__file__).resolve().parent.parent;D1=ROOT/'D1';D2=ROOT/'D2'
a=json.loads((D1/'metrics.json').read_text());b=json.loads((D2/'structure_audit.json').read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def f(x,n=2):return '—' if x is None else f'{x:.{n}f}'
def source():return f"Zenodo v1.0.0 `zenodo.zip` SHA-256 `{a['source']['zenodo_zip_sha256']}`；NOAA IBTrACS WP v04r01 SHA-256 `{a['source']['ibtracs_sha256']}`；50 个 CSV 各自 SHA-256 见 `D1/metrics.json → source.csv_manifest`。"
lines=['# L26.28 D1 强度（Colab CPU，作者输出对独立最佳路径）','',source(),'','定义：有效时刻=同台风、同 UTC、机构字段非空；P=最低中心气压 hPa，V=最大风 m/s。IBTrACS 风 kt×0.514444；CMA/JTWC 不做时距换算。R=MAE(SR)/MAE(Pangu)；Δ=MAE(SR)−MAE(Pangu)。每个时效段内同一机构、变量使用完全相同的配对行，台风整组有放回抽样 2,000 次，固定种子 20261118；区间取排序抽样序列第100/1900值（90%，非独立逐行抽样）。原始结果 `metrics.json`，计算脚本 `score.py`。','',f"原 CSV 1,814 行；有同刻最佳路径 {a['n_rows']} 行；排除 {len(a['exclusions'])} 行（Nanmadol 路径终时后），另存 `metrics.json → exclusions`。其余时效（0、6、18、78–90 h 等）未并入下面三段。",'','| 时效 | 机构 | 指标 | n（台风） | Pangu MAE / 偏差 | SR MAE / 偏差 | R | Δ 与 90% CI |','|---|---|---|---:|---:|---:|---:|---:|']
for seg,v in a['metrics'].items():
 for ag in ('CMA','JTWC','JMA'):
  for var in ('P','V'):
   z=v['agencies'][ag][var];base=z['lq'];sr=z['sr'];q=z['bootstrap'];unit='hPa' if var=='P' else 'm/s'
   lines.append(f"| {seg} | {ag} | {var} ({unit}) | {base['n']}（{q['n_storms']}） | {f(base['mae'])} / {f(base['bias'])} | {f(sr['mae'])} / {f(sr['bias'])} | {f(z['R'],3)} | {f(q['difference_sr_minus_pangu'])} [{f(q['ci90'][0])}, {f(q['ci90'][1])}] |")
lines += ['','JMA 仅描述，不参与 §4 判断。强度插值基线 n=0：`structure/data_day` 不是 lq 空间场，只给 1-D `radius_km,mean_wind_speed_ms`；无法从径向均值恢复中心气压或 2-km 双三次插值极值。不得拿径向插值当空间插值。','', '## 峰值（单列，不入判据）','定义：在该台风可核对的最佳路径时刻中选 CMA 最高风及最早并列峰时；对每个起报在峰时 ±12 h 内可用的模型时刻取最大风−同一 CMA 峰值，再对该台风 5 个起报的误差取中位。若窗口未覆盖完整 ±12 h，仍只取已公开时刻，不外推。','| 台风 | CMA 峰时 UTC | 峰风 m/s | 起报数 | Pangu 峰误差 m/s | SR 峰误差 m/s |','|---|---|---:|---:|---:|---:|']
for storm,x in a['peaks'].items():lines.append(f"| {storm} | {x['peak_time']} | {f(x['CMA_peak_ms'])} | {x['n_issues']} | {f(x['median_pangu_error_ms'])} | {f(x['median_sr_error_ms'])} |")
lines += ['','## 12 h 拆因（描述，不作因果归属）','观测强度分档按 CMA 同刻 V：<33、33–<50、≥50 m/s；其余分段仍按同一分档，n 为配对行（不同起报相关）。','| 时效 | 强度档 | n（台风） | SR 风偏差 m/s | Pangu 风偏差 m/s | SR 压偏差 hPa | Pangu 压偏差 hPa |','|---|---|---:|---:|---:|---:|---:|']
for seg,groups in a['mechanism'].items():
 for band,x in groups.items():lines.append(f"| {seg} | {band} | {x['n']}（{x['storms']}） | {f(x['sr_wind_bias_ms'])} | {f(x['pangu_wind_bias_ms'])} | {f(x['sr_pressure_bias_hpa'])} | {f(x['pangu_pressure_bias_hpa'])} |")
lines += ['','(a) WRF 起转、使 SR 前段偏弱：12 h 合并数据 SR 风偏强、压偏低，与“弱初态单独导致本次短时效变差”方向相反；不能排除 WRF 起转参与个别样本，因无逐时 WRF 真值。','(b) 双向注意力把后段增强传回前段：代码支持无掩码整段注意力，但观测偏差不足以识别因果；无权重，无法做未来帧消融，不能排除。','(c) 样本偶然：12 h 台风组自助气压、风 MAE 差 90% 区间均跨零，不能排除。','(d) 作者的“强台风训练导致高估”：12 h 风正偏、压负偏与高估符号相符，但 12 h 样本全部落 <33 m/s，无法从本段辨认“强台风训练”这一原因；不能排除也不能证实。更长时效强风档反而普遍低估，不支持把全时效误差概括为高估。','',f"脚本 SHA-256：`stage.py` {sha(D1/'stage.py')}；`score.py` {sha(D1/'score.py')}；结果 `metrics.json` {sha(D1/'metrics.json')}。数据源与许可：Zhao 等 Zenodo DOI 10.5281/zenodo.19205784（CC BY 4.0）；NOAA IBTrACS DOI 10.25921/82ty-9e16。"]
(D1/'D1_强度.md').write_text('\n'.join(lines)+'\n')
profiles=b['profile_files']; lines=['# L26.28 D2 结构可核查性','',source(),'',f"`structure/data_day` 实际 {b['profile_file_count']} 个文件，10 台风 × 1/2/3 d × lq/sr/gt；变量只有 `radius_km,mean_wind_speed_ms` 的方位平均径向剖面（每文件一个剖面）。无 2-D 风格网、纬经度、中心、起报时次或 UTC 有效时刻；目录的 1/2/3 d 是名义日数，不能逆推出绝对时刻或中心。作者单独发布的 `val_Yinxing` 有带 UTC 的 .npy 场，但不是这 10 个检验台风，不能移植。下面逐文件清单的空缺是源文件真实缺失，不是填 0。",'','| 台风 | 名义日 | 类型 | 径向点数 | 范围 km | 剖面最大风半径 km（描述） | 文件 SHA-256 |','|---|---|---|---:|---:|---:|---|']
for p in profiles:lines.append(f"| {p['storm']} | {p['day']} | {p['kind']} | {p['n_radius']} | {f(p['radius_min_km'])}–{f(p['radius_max_km'])} | {f(p['profile_peak_radius_km'])} | `{p['sha256']}` |")
lines+=['','几何口径：表中 radius 是原包给出的 0–300 km 径向距离，不是地理坐标；源文件不提供中心的经纬度或中心选择方法。不能从径向均值重建 2 km 经纬网，也不能证明剖面最大值半径采用了 L26.18 的“3 km 环全方位平均，0–2 RMW 覆盖 ≥29/36 扇区”的有效中心规则。所谓 Pangu、SR 的剖面峰半径仅为描述，不能与 SAR 直接做 §4 配对。','', '## SAR 配对与散射计回退',f"CyclObs `getData` 按 D0 的 10 个 sid、`data_url` 去重、`eye_in_acq=true` 查询。若乐观地假定每台风 5 个起报的 +24/+48/+72 h 都对应这 3 个未标时剖面，±3 h 得到 {b['nominal_unique_scene_count']} 景、{b['nominal_unique_storm_count']} 台风的名义候选上界（`structure_audit.json → nominal_scene_candidates`，不是实际匹配数）。由于没有任何一个公开剖面带起报/有效 UTC，严格可验证的剖面—SAR 配对数为 {b['qualified_scene_count']}；不能据此声称真实过境为零。D0 的 67 景是与任一强度 CSV 时刻相近的候选，不是与结构场匹配。",'','SAR 的 A（≥3 景、≥2 台风）在“可验证配对”层面无法成立；中心距独立最佳路径 ≤30 km、SAR 环覆盖和 C 取法敏感性都未核，不能把时距候选误充合格景。SR/空间插值/Pangu 对 SAR RMW 的中位相对差均“未计算”，不是 0 或无穷。','', 'ASCAT OSI-104-b/-c（12.5 km coastal）和 HY-2 系 OSI SAF 风产品是 CC BY 4.0；历史 EUMETSAT Data Store 产品下载即使非受限也要求 API token，OSI SAF FTP 要注册凭据且仅近 3 天。未使用凭据或拉取 2022–24 年轨道。另因本包没有检验台风任一 2-D 经纬定位风场及象限，无法计算模型四象限 R17 或 2RMW 外方位廓线，即使可取卫星产品也无法作指定对照。散射计有效配对和 R17 差均“未计算”。参 https://osi-saf.eumetsat.int/products/osi-104-c 与 https://user.eumetsat.int/resources/user-guides/data-store-detailed-guide 。','',f"脚本 SHA-256：`audit_structure.py` {sha(D2/'audit_structure.py')}；数据 `structure_audit.json` {sha(D2/'structure_audit.json')}。逐文件源 SHA 在上表及 JSON。"]
(D2/'D2_结构.md').write_text('\n'.join(lines)+'\n')
ct=['# L26.28 §4 判据逐条数值表（仅事实列；最终判定归 Lead）','',source(),'','§4 预先写定，未修改。各比值 R=SR MAE/Pangu MAE；差值区间为 SR−Pangu 的台风配对 2,000 次重抽。表内“是否成立”只指逐条门槛的可检验性，不是最终裁决。','', '| 判据 | 实算数值或状态 | 是否成立 |','|---|---|---|']
for seg in ('24-72h','96-168h'):
 for ag in ('CMA','JTWC'):
  for var,lim in (('P',.8),('V',.8)):
   z=a['metrics'][seg]['agencies'][ag][var];ci=z['bootstrap']['ci90'];ct.append(f"| 值得用 1/2：{seg} {ag} {var} R≤0.8"+(' 且 Δ 90% CI 不含0' if var=='P' else '')+f" | n={z['sr']['n']}，R={f(z['R'],3)}，Δ={f(z['bootstrap']['difference_sr_minus_pangu'])} [{f(ci[0])}, {f(ci[1])}] | {'是' if z['R']<=lim and (var!='P' or ci[0]*ci[1]>0) else '否'} |")
ct += [f"| 值得用 3：SAR A 与 SR RMW≤0.25，且不劣于插值/Pangu | 严格配对 n={b['qualified_scene_count']}；名义候选 {b['nominal_unique_scene_count']} 景/{b['nominal_unique_storm_count']} 台风；SR/插值/Pangu 中位差未计算 | 无法评价 |",'| 值得用 3 回退：散射计 R17≤0.25，且不劣于插值 | 历史数据渠道需 token/注册；作者无空间风场，R17 未计算 | 无法评价 |','| 值得用 4：生成器权重或随包更新可运行，Colab 单卡推理 | D0 两版无生成器权重；随机权重架构前向跑通≠作者权重可用 | 否 |']
for seg in ('24-72h','96-168h'):
 for ag in ('CMA','JTWC'):
  for var in ('P','V'):
   z=a['metrics'][seg]['agencies'][ag][var];ct.append(f"| 放弃：{seg} {ag} {var} R≥0.95 | n={z['sr']['n']}，R={f(z['R'],3)} | {'是' if z['R']>=.95 else '否'} |")
ct += ['| 放弃：SAR A 成立且 SR RMW >0.40 或劣于插值 | 严格配对 n=0、RMW/插值未计算 | 无法评价 |','| 放弃：改善仅 CMA 有，换 JTWC 消失 | 24–72 h 气压 CMA R=0.767、JTWC R=0.948 且区间跨 0；96–168 h 两家 R 在中间带。按“消失”是否达到 §4 操作定义须 Lead 裁定 | 需 Lead 判读 |','| 不判条件：样本不足 | SAR 可验证配对 n=0；散射计 n=0（未完成实际配对） | 是（数据可评价性不足） |','| 不判条件：R 在 (0.8,0.95)、区间含0 | 24–72 h JTWC P R=0.948，区间跨 0；96–168 h CMA/JTWC P R=0.869/0.892 | 是 |','',f"溯源：`D1/score.py` SHA-256 `{sha(D1/'score.py')}`；`D1/metrics.json` `{sha(D1/'metrics.json')}`；`D2/audit_structure.py` `{sha(D2/'audit_structure.py')}`；`D2/structure_audit.json` `{sha(D2/'structure_audit.json')}`；D0 权重证据 `D0/D0_可得性.md`、`D0/members_v1.json`/`members_latest.json`。源 CSV 每文件 SHA-256：`D1/metrics.json → source.csv_manifest`；结构每文件 SHA-256：`D2/structure_audit.json → profile_files`。",'','数据来源：Zhao 等 Zenodo 10.5281/zenodo.19205784（CC BY 4.0）；NOAA IBTrACS v04r01 DOI 10.25921/82ty-9e16；Ifremer CyclObs https://cyclobs.ifremer.fr/app/docs/API_usage.html；OSI SAF CC BY 4.0。']
(D2/'criteria_table.md').write_text('\n'.join(ct)+'\n')
print('RENDERED',*[str(x) for x in (D1/'D1_强度.md',D2/'D2_结构.md',D2/'criteria_table.md')])
